      columns: [
        { key: 'name', title: 'Устройство' },
        { key: 'value', title: 'Визиты', align: 'end' },
        { key: 'share', title: 'Доля', align: 'end' },
      ],
      rows: deviceSplit(days).parts.map((p) => ({
        name: p.name,
        value: fmtInt(p.value),
        share: fmtPercent(p.share, 1),
      })),
    }),
  },
  {
    id: 'services',
    title: 'Нагрузка на сервисы',
    subtitle: () => 'сейчас',
    minW: 3,
