}

/* ---------- Полосы (топ страниц) ---------- */
.bars {
  margin: 0;
  padding: 0;
  list-style: none;
}
.bars__row {
  display: grid;
  grid-template-columns: minmax(70px, 38%) 1fr auto;
  align-items: center;
  gap: 10px;
  font-size: 12px;
  border-radius: 6px;
}
.bars__label {
  color: var(--text-secondary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bars__track {
  display: flex;
  align-items: center;
  height: 100%;
  padding-right: 4px;
}
.bars__bar {
  height: 16px;
  min-width: 2px;
  background: var(--series-1);
  border-radius: 0 4px 4px 0; /* скруглён только конец данных, у базовой линии — прямо */
  transition: filter 0.1s;
}
.bars__row.is-hover .bars__bar {
  filter: brightness(1.12);
}
.bars__value {
  min-width: 44px;
  text-align: right;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

/* ---------- Устройства ---------- */
.devices {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.devices__total {
  display: flex;
  align-items: baseline;
  gap: 8px;
}
.devices__num {
  font-size: 26px;
  line-height: 30px;
  font-weight: 600;
}
.devices__cap {
  font-size: 12px;
  color: var(--text-muted);
}
.seg {
  display: flex;
  gap: 2px;
  height: 28px;
}
.seg__block {
  display: flex;
  align-items: center;
  padding-left: 10px;
  box-sizing: border-box;
  border-radius: 4px;
  color: #fff;
  font-size: 12px;
  font-weight: 600;
  white-space: nowrap;
  transition: filter 0.1s;
}
.seg__block.is-hover {
  filter: brightness(1.1);
}

/* ---------- Индикаторы ---------- */
.meters {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.meters_compact {
  gap: 8px;
}
.meter__head {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 5px;
  font-size: 12px;
}
.meter__name {
  flex: 1;
  min-width: 0;
  color: var(--text-secondary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.meter__state {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: var(--text-primary);
}
.meter__state svg {
  flex: none;
}
.meter__num {
  min-width: 34px;
  text-align: right;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.meter__track {
  height: 8px;
  border-radius: 4px;
  --fill: var(--accent);
  background: color-mix(in srgb, var(--fill) 22%, var(--surface-1));
  overflow: hidden;
}
.meter__track_warning {
  --fill: var(--status-warning);
}
.meter__track_critical {
  --fill: var(--status-critical);
}
.meter__fill {
  height: 100%;
  border-radius: 4px;
  background: var(--fill, var(--accent));
}
.meter__fill_normal {
  background: var(--accent);
}
.meter__fill_warning {
  background: var(--status-warning);
}
.meter__fill_critical {
  background: var(--status-critical);
}

/* ---------- Таблицы ---------- */
.scroll {
  height: 100%;
  overflow: auto;
  margin: 0 -16px;
  padding: 0 16px;
}
.table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
}
.table th {
  position: sticky;
  top: 0;
  z-index: 1;
  padding: 6px 12px 6px 0;
  text-align: left;
  font-weight: 500;
  color: var(--text-muted);
  background: var(--surface-1);
  box-shadow: inset 0 -1px 0 var(--grid);
}
.table td {
  padding: 7px 12px 7px 0;
  vertical-align: top;
  color: var(--text-primary);
  border-bottom: 1px solid var(--grid);
  font-variant-numeric: tabular-nums;
}
.table .is-end {
  text-align: right;
  padding-right: 0;
}
.table .nowrap {
  white-space: nowrap;
}
.status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.status_good svg {
  color: var(--status-good);
}
.status_warning svg {
  color: var(--status-warning);
}
.status_serious svg {
  color: var(--status-serious);
}
.status_critical svg {
  color: var(--status-critical);
}
EOF
