args.command:
cat > /tmp/pw/e2e.mjs <<'EOF'
import { chromium } from 'playwright';
const b = await chromium.launch();
const ctx = await b.newContext({ viewport: { width: 1400, height: 1000 } });
const p = await ctx.newPage();
const errs = [];
p.on('console', m => m.type() === 'error' && errs.push(m.text()));
p.on('pageerror', e => errs.push(String(e)));
await p.goto('http://[::1]:5199/');
await p.waitForSelector('.widget');
await p.waitForTimeout(300);

const pos = () => p.evaluate(() => Object.fromEntries([...document.querySelectorAll('.grid__item')].map(el => {
  const t = el.querySelector('.widget__title').textContent;
  const m = /translate\(([-\d.]+)px, ([-\d.]+)px\)/.exec(el.style.transform);
  return [t, `${Math.round(+m[1])},${Math.round(+m[2])} ${Math.round(parseFloat(el.style.width))}x${Math.round(parseFloat(el.style.height))}`];
})));
const head = (t) => p.locator('.widget', { has: p.locator('h2', { hasText: t }) }).locator('.widget__head');
const ok = (name, cond, extra='') => console.log((cond ? 'PASS ' : 'FAIL ') + name + (extra ? '  ' + extra : ''));

const before = await pos();

// 1. Перетаскивание «Топ страниц» вверх на место «Трафика» (обмен/вытеснение)
let hb = await head('Топ страниц').boundingBox();
await p.mouse.move(hb.x + 120, hb.y + 15);
await p.mouse.down();
await p.mouse.move(hb.x + 130, hb.y - 100, { steps: 6 });
await p.mouse.move(hb.x + 140, hb.y - 380, { steps: 10 });
await p.screenshot({ path: '/tmp/pw/drag-mid.png' });
const midPlaceholder = await p.locator('.grid__placeholder').count();
await p.mouse.up();
await p.waitForTimeout(400);
const afterDrag = await pos();
ok('placeholder shown during drag', midPlaceholder === 1);
ok('drag moved the widget', afterDrag['Топ страниц'] !== before['Топ страниц'], `${before['Топ страниц']} -> ${afterDrag['Топ страниц']}`);
const rects = await p.evaluate(() => [...document.querySelectorAll('.grid__item')].map(e => e.getBoundingClientRect()).map(r => [r.left, r.top, r.right, r.bottom]));
let overlap = false;
for (let i = 0; i < rects.length; i++) for (let j = i + 1; j < rects.length; j++) {
  const a = rects[i], c = rects[j];
  if (a[0] < c[2] - 1 && a[2] > c[0] + 1 && a[1] < c[3] - 1 && a[3] > c[1] + 1) overlap = true;
}
ok('no overlaps after drag', !overlap);
console.log(JSON.stringify(afterDrag, null, 1));

// 2. Escape отменяет перетаскивание
const snap = await pos();
hb = await head('Последние события').boundingBox();
await p.mouse.move(hb.x + 200, hb.y + 15);
await p.mouse.down();
await p.mouse.move(hb.x - 300, hb.y - 200, { steps: 8 });
await p.keyboard.press('Escape');
await p.mouse.up();
await p.waitForTimeout(300);
ok('Escape cancels drag', JSON.stringify(await pos()) === JSON.stringify(snap));

// 3. Ресайз
const rw = p.locator('.widget', { has: p.locator('h2', { hasText: 'Последние события' }) }).locator('.widget__resize');
const rb = await rw.boundingBox();
const w0 = (await pos())['Последние события'];
await p.mouse.move(rb.x + 11, rb.y + 11);
await p.mouse.down();
await p.mouse.move(rb.x - 150, rb.y + 90, { steps: 8 });
await p.mouse.up();
await p.waitForTimeout(300);
const w1 = (await pos())['Последние события'];
ok('resize changed size', w0.split(' ')[1] !== w1.split(' ')[1], `${w0} -> ${w1}`);
// минимальный размер
await p.mouse.move(rb.x - 150 + 11, rb.y + 90 + 11);
const rb2 = await rw.boundingBox();
await p.mouse.move(rb2.x + 11, rb2.y + 11);
await p.mouse.down();
await p.mouse.move(rb2.x - 900, rb2.y - 900, { steps: 8 });
await p.mouse.up();
await p.waitForTimeout(300);
const w2 = (await pos())['Последние события'];
ok('resize clamps to min', true, w2);

// 4. Клавиатура
await p.locator('.widget', { has: p.locator('h2', { hasText: 'Трафик' }) }).locator('.widget__grip').focus();
const k0 = (await pos())['Трафик по каналам'];
await p.keyboard.press('ArrowRight');
await p.waitForTimeout(250);
const k1 = (await pos())['Трафик по каналам'];
ok('keyboard ArrowRight moves (or clamps)', true, `${k0} -> ${k1}`);
await p.keyboard.press('Shift+ArrowLeft');
await p.waitForTimeout(250);
const k2 = (await pos())['Трафик по каналам'];
ok('keyboard Shift+Arrow resizes', k2.split(' ')[1] !== k1.split(' ')[1], `${k1} -> ${k2}`);
const focused = await p.evaluate(() => document.activeElement?.className);
ok('focus kept on grip after move', /widget__grip/.test(focused), focused);
console.log('live:', await p.locator('.sr-only[aria-live]').textContent());

// 5. Тултип на линейном графике
const svg = p.locator('.linechart__svg');
const sb = await svg.boundingBox();
await p.mouse.move(sb.x + sb.width / 2, sb.y + 60);
await p.waitForTimeout(150);
ok('line tooltip appears', await p.locator('.tip').count() === 1, (await p.locator('.tip').innerText().catch(() => '')).replace(/\n/g, ' | '));
await p.screenshot({ path: '/tmp/pw/tip.png', clip: { x: sb.x - 20, y: sb.y - 60, width: sb.width + 40, height: sb.height + 80 } });
await p.mouse.move(5, 5);
await svg.focus();
await p.keyboard.press('ArrowLeft');
ok('line tooltip via keyboard', await p.locator('.tip').count() === 1);
await p.keyboard.press('Escape');

// 6. Таблица
